<template>
  <section class="page task-page">
    <div class="page-header"><h1>故障预测任务配置</h1><el-button v-if="canCreate" type="primary" :icon="Plus" @click="openCreate">新增任务</el-button></div>
    <el-card shadow="never" class="filter-card"><el-form inline class="task-filter-form">
      <el-form-item label="任务名称"><el-input v-model="query.keyword" clearable placeholder="任务名称" /></el-form-item>
      <el-form-item label="创建者"><el-input v-model="query.creatorName" clearable placeholder="创建者" /></el-form-item><el-form-item label="创建日期"><el-date-picker v-model="query.createdDate" type="date" value-format="YYYY-MM-DD" clearable placeholder="请选择日期" /></el-form-item><el-form-item class="model-filter-item" label="AI预测模型"><el-select v-model="query.modelId" clearable placeholder="全部"><el-option v-for="item in models" :key="item.id" :label="item.modelName" :value="item.id" /></el-select></el-form-item>
      <el-form-item><el-button type="primary" :icon="Search" @click="search">查询</el-button><el-button :icon="RefreshLeft" @click="reset">重置</el-button></el-form-item>
    </el-form></el-card>
    <el-card shadow="never"><el-table v-loading="loading" :data="filteredRecords" stripe>
      <el-table-column prop="taskName" label="任务名称" min-width="180" show-overflow-tooltip /><el-table-column prop="creatorName" label="创建者" width="110"><template #default="{ row }">{{ row.creatorName || '-' }}</template></el-table-column><el-table-column prop="createdAt" label="创建时间" width="175"><template #default="{ row }">{{ formatTime(row.createdAt) }}</template></el-table-column>
      <el-table-column prop="targetNameSnapshot" label="预测对象" min-width="180" show-overflow-tooltip /><el-table-column prop="modelNameSnapshot" label="AI预测模型" min-width="180" show-overflow-tooltip />
      <el-table-column prop="lastExecTime" label="上一次预测时间" width="175"><template #default="{ row }">{{ formatTime(row.lastExecTime) }}</template></el-table-column>
      <el-table-column label="任务次数 / 故障数量" width="155"><template #default="{ row }"><el-button link type="primary" @click="openDetail(row)">{{ row.executionCount || 0 }} / {{ row.resultCount || 0 }}</el-button></template></el-table-column>
      <el-table-column label="操作" width="235" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openDetail(row)">查看</el-button><el-button v-if="canUpdate" link type="primary" :icon="Edit" @click="openEdit(row)">编辑</el-button><el-button v-if="canExecute" link type="success" :icon="VideoPlay" @click="execute(row)">立即执行</el-button><el-button v-if="canDelete" link type="danger" :icon="Delete" @click="remove(row)">删除</el-button></template></el-table-column>
    </el-table><div class="table-footer"><el-pagination v-model:current-page="query.pageNo" v-model:page-size="query.pageSize" :total="total" layout="total, sizes, prev, pager, next" @change="load" /></div></el-card>

    <el-drawer v-model="formVisible" :title="editingId ? '编辑预测任务' : '新增预测任务'" size="620px" destroy-on-close @closed="resetForm"><el-form ref="formRef" :model="form" :rules="rules" label-position="top">
      <el-form-item label="任务名称" prop="taskName"><el-input v-model="form.taskName" maxlength="150" show-word-limit placeholder="请输入任务名称" /></el-form-item>
      <el-form-item label="预测对象" prop="targetId"><div class="target-row"><el-select v-model="form.targetType" @change="form.targetId = ''"><el-option label="业务系统" value="BUSINESS_SYSTEM" /><el-option label="分布式数据库" value="DB_RESOURCE" /></el-select><el-select v-model="form.targetId" filterable placeholder="请选择具体对象"><el-option v-for="item in targetOptions" :key="item.id" :label="item.name" :value="item.id" /></el-select></div></el-form-item>
      <el-form-item label="AI预测模型" prop="modelId"><el-select v-model="form.modelId" filterable placeholder="请选择启用的故障预测模型" style="width:100%"><el-option v-for="item in models" :key="item.id" :label="item.modelName" :value="item.id" /></el-select><div class="model-tip">{{ selectedModel?.description || '请选择适用于故障预测的 AI 模型' }}</div></el-form-item>
      <el-form-item label="预测指标" prop="metrics"><div class="metric-header"><span></span><span><el-button link type="primary" @click="form.metrics = [...metrics]">全选</el-button><span class="divider">|</span><el-button link @click="form.metrics = []">清空</el-button></span></div><el-checkbox-group v-model="form.metrics" class="metric-grid"><el-checkbox v-for="item in metrics" :key="item" :label="item">{{ item }}</el-checkbox></el-checkbox-group><div class="model-tip">已选 {{ form.metrics.length }} / {{ metrics.length }} 项</div></el-form-item>
      <el-form-item class="schedule-form-item" label="定时预测设置" prop="schedules" required><div class="schedule-label">已添加 {{ form.schedules.length }} 条定时规则：</div><div v-for="(item, index) in form.schedules" :key="item.id" class="schedule-row"><span><el-icon><Clock /></el-icon>{{ scheduleText(item) }}</span><el-button link type="danger" :icon="Delete" aria-label="删除定时规则" @click="form.schedules.splice(index, 1)" /></div><div class="schedule-builder"><div class="schedule-builder-title">添加定时规则</div><label class="schedule-field"><span>时间</span><input v-model="scheduleDraft.time" type="time" /></label><label class="schedule-field"><span>预测时间范围</span><el-select v-model="scheduleDraft.predictionWindowHours"><el-option v-for="hour in [1,2,4,12,24]" :key="hour" :label="`${hour} 小时`" :value="hour" /></el-select></label><div class="schedule-field"><span>重复周期</span><el-radio-group v-model="scheduleDraft.repeatType" class="repeat-type-control"><el-radio-button label="daily">每日</el-radio-button><el-radio-button label="weekly">每周</el-radio-button></el-radio-group></div><el-checkbox-group v-if="scheduleDraft.repeatType === 'weekly'" v-model="scheduleDraft.weekDays" class="week-days"><el-checkbox v-for="day in weekDays" :key="day" :label="day">{{ day }}</el-checkbox></el-checkbox-group><el-button plain type="primary" :icon="Plus" class="add-schedule-button" @click="addSchedule">添加此定时规则</el-button></div></el-form-item>
      <el-form-item label="创建者"><el-input :model-value="userStore.realName || userStore.username || '-'" disabled /><div class="model-tip">创建者信息自动填充，不可修改</div></el-form-item>
    </el-form><template #footer><div class="drawer-footer"><el-button @click="formVisible=false">取消</el-button><el-button type="primary" :loading="submitting" @click="save">{{ editingId ? '保存更新' : '提交保存' }}</el-button></div></template></el-drawer>
    <el-drawer v-model="detailVisible" title="预测任务详情" size="580px">
      <el-descriptions v-if="detail" :column="1" border>
        <el-descriptions-item label="任务名称">{{ detail.taskName }}</el-descriptions-item><el-descriptions-item label="创建者">{{ detail.creatorName || '-' }}</el-descriptions-item><el-descriptions-item label="预测对象">{{ detail.targetNameSnapshot }}</el-descriptions-item><el-descriptions-item label="AI预测模型">{{ detail.modelNameSnapshot }}</el-descriptions-item><el-descriptions-item label="预测指标">{{ detail.metricCodes }}</el-descriptions-item><el-descriptions-item label="定时规则">{{ detailSchedules.map(scheduleText).join('；') || '-' }}</el-descriptions-item><el-descriptions-item label="执行次数 / 故障数量">{{ detail.executionCount || 0 }} / {{ detail.resultCount || 0 }}</el-descriptions-item><el-descriptions-item label="上一次预测时间">{{ formatTime(detail.lastExecTime) }}</el-descriptions-item>
      </el-descriptions>
      <el-tabs v-if="detail" v-model="detailTab" class="detail-tabs">
        <el-tab-pane label="任务次数列表" name="executions">
          <el-table :data="detail.executionRecords" size="small"><el-table-column prop="executionStatus" label="状态" width="90" /><el-table-column label="开始时间" min-width="155"><template #default="{ row }">{{ formatTime(row.startTime) }}</template></el-table-column><el-table-column label="结束时间" min-width="155"><template #default="{ row }">{{ formatTime(row.endTime) }}</template></el-table-column><el-table-column prop="resultCount" label="结果数" width="80" /></el-table>
        </el-tab-pane>
        <el-tab-pane label="故障数量列表" name="faults">
          <el-table :data="detail.faultReports || []" size="small" empty-text="暂无故障记录" @selection-change="selectedFaultReports = $event"><el-table-column type="selection" width="46" /><el-table-column prop="reportCode" label="故障ID" min-width="125" /><el-table-column label="开始执行时间" min-width="145"><template #default="{ row }">{{ formatTime(row.alertTime) }}</template></el-table-column><el-table-column prop="faultType" label="故障问题" min-width="145" show-overflow-tooltip /><el-table-column label="操作" width="72"><template #default="{ row }"><el-button type="primary" size="small" @click="openFaultAlert(row.reportCode)">查看</el-button></template></el-table-column></el-table>
          <div class="fault-list-actions"><span v-if="selectedFaultReports.length !== 1">请选择一条故障记录</span><el-button type="primary" :disabled="selectedFaultReports.length !== 1" @click="openFaultAlert()">查看</el-button></div>
        </el-tab-pane>
      </el-tabs>
      <div class="detail-actions"><el-button type="primary" :disabled="selectedFaultReports.length !== 1" @click="openFaultAlert()">查看关联预警</el-button></div>
    </el-drawer>
  </section>
</template>
<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { Clock, Delete, Edit, Plus, RefreshLeft, Search, VideoPlay } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox, type FormInstance } from 'element-plus'
import { createFaultTask, deleteFaultTask, executeFaultTask, getAiModels, getFaultTaskDetail, getFaultTasks, type AiModelItem, type FaultTaskDetail, type FaultTaskItem, updateFaultTask } from '@/api/modules/ai'
import { getBusinessSystems, getDbResources } from '@/api/modules/ledger'
import { useUserStore } from '@/stores/user'
import { useRouter } from 'vue-router'

type Schedule = { id: string; time: string; repeatType: 'daily' | 'weekly'; weekDays: string[]; predictionWindowHours: number }
const metrics = ['CPU','内存','磁盘IO','网络带宽','系统负载','进程状态','数据库连接数','SQL响应时长','事务成功率','表空间使用率','索引命中率','锁等待次数','日志增长速率','缓存命中率','业务请求时延','数据入库速率','业务成功率','批量写库吞吐量','连接池使用率','等待线程数','平均连接等待时长','连接超时次数']
const weekDays = ['周一','周二','周三','周四','周五','周六','周日']
const router = useRouter(); const userStore = useUserStore(); const loading=ref(false); const submitting=ref(false); const total=ref(0); const records=ref<FaultTaskItem[]>([]); const models=ref<AiModelItem[]>([]); const systems=ref<{id:string;name:string}[]>([]); const databases=ref<{id:string;name:string}[]>([]); const formVisible=ref(false); const detailVisible=ref(false); const detailTab=ref<'executions'|'faults'>('executions'); const selectedFaultReports=ref<FaultTaskDetail['faultReports']>([]); const editingId=ref(''); const detail=ref<FaultTaskDetail>(); const formRef=ref<FormInstance>()
const query=reactive({pageNo:1,pageSize:10,keyword:'',creatorName:'',createdDate:'',modelId:''}); const form=reactive({taskName:'',targetType:'BUSINESS_SYSTEM' as 'BUSINESS_SYSTEM'|'DB_RESOURCE',targetId:'',modelId:'',metrics:[...metrics] as string[],schedules:[] as Schedule[]}); const scheduleDraft=reactive({time:'08:00',repeatType:'daily' as 'daily'|'weekly',weekDays:[] as string[],predictionWindowHours:4}); const rules={taskName:[{required:true,message:'请输入任务名称',trigger:'blur'}],targetId:[{required:true,message:'请选择预测对象',trigger:'change'}],modelId:[{required:true,message:'请选择AI预测模型',trigger:'change'}]}; const canCreate=computed(()=>userStore.hasPermission('ai:task:create')); const canUpdate=computed(()=>userStore.hasPermission('ai:task:update')); const canDelete=computed(()=>userStore.hasPermission('ai:task:delete')); const canExecute=computed(()=>userStore.hasPermission('ai:task:execute')); const targetOptions=computed(()=>form.targetType==='BUSINESS_SYSTEM'?systems.value:databases.value); const selectedModel=computed(()=>models.value.find(item=>item.id===form.modelId)); const filteredRecords=computed(()=>records.value); const detailSchedules=computed(()=>parseSchedules(detail.value?.scheduleRule))
function formatTime(value?:string){return value?value.replace('T',' ').slice(0,16):'-'} function parseSchedules(value?:string):Schedule[]{try{const parsed=JSON.parse(value || '[]');return Array.isArray(parsed)?parsed.map((item,index)=>({id:item.id || `legacy-rule-${index}`,time:item.time || '08:00',repeatType:item.repeatType === 'weekly' ? 'weekly' : 'daily',weekDays:Array.isArray(item.weekDays)?item.weekDays:[],predictionWindowHours:[1,2,4,12,24].includes(Number(item.predictionWindowHours))?Number(item.predictionWindowHours):4})):[]}catch{return[]}} function scheduleText(item:Schedule){const hours=[1,2,4,12,24].includes(Number(item.predictionWindowHours))?item.predictionWindowHours:4;return item.repeatType==='daily'?`每日 ${item.time}，预测未来 ${hours} 小时`:`每周 ${item.weekDays.join('、')} ${item.time}，预测未来 ${hours} 小时`}
async function loadOptions(){const [modelPage,systemPage,dbPage]=await Promise.all([getAiModels({pageNo:1,pageSize:200,modelType:'FAULT_PREDICTION',status:'ENABLED'}),getBusinessSystems({pageNo:1,pageSize:200}),getDbResources({pageNo:1,pageSize:200})]);models.value=modelPage.records;systems.value=systemPage.records.map(item=>({id:item.id,name:item.name}));databases.value=dbPage.records.map(item=>({id:item.id,name:item.name}))} async function load(){loading.value=true;try{const page=await getFaultTasks(query);records.value=page.records;total.value=page.total}finally{loading.value=false}} function search(){query.pageNo=1;load()} function reset(){query.keyword='';query.creatorName='';query.createdDate='';query.modelId='';search()} function resetForm(){editingId.value='';form.taskName='';form.targetType='BUSINESS_SYSTEM';form.targetId='';form.modelId='';form.metrics=[...metrics];form.schedules=[];scheduleDraft.time='08:00';scheduleDraft.repeatType='daily';scheduleDraft.weekDays=[];scheduleDraft.predictionWindowHours=4;formRef.value?.clearValidate()} function openCreate(){formVisible.value=true} function openEdit(row:FaultTaskItem){editingId.value=row.id;form.taskName=row.taskName;form.targetType=row.targetType;form.targetId=row.targetId;form.modelId=row.modelId||'';form.metrics=row.metricCodes.split(',').filter(Boolean)||[];form.schedules=parseSchedules(row.scheduleRule);formVisible.value=true} async function openDetail(row:FaultTaskItem){detailTab.value='executions';selectedFaultReports.value=[];detailVisible.value=true;try{detail.value=await getFaultTaskDetail(row.id)}catch{detailVisible.value=false}} function openFaultAlert(reportCode?:string){const code=reportCode || (selectedFaultReports.value.length === 1 ? selectedFaultReports.value[0].reportCode : undefined);if (!code) return;detailVisible.value=false;router.push({name:'FaultAlert',query:{faultId:code}})} function addSchedule(){if(scheduleDraft.repeatType==='weekly'&&!scheduleDraft.weekDays.length){ElMessage.warning('每周规则至少选择一个星期');return}if(form.schedules.some(item=>item.time===scheduleDraft.time&&item.repeatType===scheduleDraft.repeatType&&item.weekDays.join(',')===scheduleDraft.weekDays.join(','))){ElMessage.warning('该定时规则已存在');return}form.schedules.push({id:`rule-${Date.now()}`,time:scheduleDraft.time,repeatType:scheduleDraft.repeatType,weekDays:[...scheduleDraft.weekDays],predictionWindowHours:scheduleDraft.predictionWindowHours})} async function save(){const valid=await formRef.value?.validate().catch(()=>false);if(!valid)return;if(!form.metrics.length){ElMessage.warning('请至少选择一个预测指标');return}if(!form.schedules.length){ElMessage.warning('请至少添加一条定时预测规则');return}submitting.value=true;try{const payload={taskName:form.taskName.trim(),modelId:form.modelId,targetType:form.targetType,targetId:form.targetId,metricCodes:form.metrics,schedules:form.schedules.map(({time,repeatType,weekDays,predictionWindowHours})=>({time,repeatType,weekDays,predictionWindowHours}))};if(editingId.value)await updateFaultTask(editingId.value,payload);else await createFaultTask(payload);ElMessage.success('保存成功');formVisible.value=false;await load()}finally{submitting.value=false}} async function execute(row:FaultTaskItem){await ElMessageBox.confirm(`确认受理「${row.taskName}」并等待 AI 引擎处理吗？`,'立即执行',{type:'warning'});await executeFaultTask(row.id);ElMessage.success('任务已受理，等待 AI 引擎处理');await load()} async function remove(row:FaultTaskItem){await ElMessageBox.confirm(`确认删除「${row.taskName}」吗？`,'删除任务',{type:'warning'});await deleteFaultTask(row.id);ElMessage.success('删除成功');await load()} loadOptions().then(load)
</script>
<style scoped>
.page-header{display:flex;align-items:center;justify-content:space-between;margin-bottom:20px}.page-header h1{margin:0;font-size:22px;color:#1f2937}.filter-card{margin-bottom:16px}.task-filter-form{display:flex;flex-wrap:wrap;align-items:flex-start;column-gap:0}.model-filter-item :deep(.el-select){width:260px}.table-footer{display:flex;justify-content:flex-end;padding-top:16px}.target-row{display:flex;gap:10px;width:100%}.target-row>*:first-child{width:34%}.target-row>*:last-child{flex:1}.model-tip,.schedule-label{margin-top:6px;color:#94a3b8;font-size:12px}.metric-header{display:flex;justify-content:space-between;width:100%;margin-bottom:8px}.divider{color:#cbd5e1;margin:0 8px}.metric-grid{display:grid;width:100%;grid-template-columns:repeat(3,minmax(0,1fr));gap:10px;padding:14px;border:1px solid #dbe4f5;border-radius:10px;background:#fbfcff}.schedule-form-item{width:100%}.schedule-form-item :deep(.el-form-item__content){display:block;width:100%;min-width:0}.schedule-label,.schedule-row,.schedule-builder{box-sizing:border-box;width:100%}.schedule-row{display:flex;align-items:center;justify-content:space-between;margin-top:8px;padding:11px 12px;border:1px solid #bfd0fb;border-radius:10px;background:#f5f8ff;color:#2857b7}.schedule-row span{display:flex;align-items:center;gap:8px;font-size:13px;min-width:0}.schedule-row span:last-child{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.schedule-builder{display:grid;gap:14px;margin-top:14px;padding:14px;border:1px solid #dbe4f5;border-radius:10px;background:#fbfcff}.schedule-builder-title{font-size:14px;font-weight:600;color:#334155}.schedule-field{display:grid;gap:8px;color:#334155;font-size:13px;font-weight:600;width:100%}.schedule-field input{box-sizing:border-box;width:100%;height:36px;padding:0 12px;border:1px solid #d7e1f1;border-radius:10px;background:#fff;color:#334155}.schedule-field :deep(.el-select){width:100%}.repeat-type-control{display:flex;width:100%}.repeat-type-control :deep(.el-radio-button){flex:1}.repeat-type-control :deep(.el-radio-button__inner){width:100%;border-radius:10px!important;box-shadow:none}.repeat-type-control :deep(.el-radio-button:first-child .el-radio-button__inner){border-left:1px solid #d7e1f1}.week-days{display:flex;flex-wrap:wrap;gap:10px;margin:0}.add-schedule-button{width:100%;margin-top:2px}.execution-summary{margin-top:18px}.execution-title{margin-bottom:10px;font-weight:600;color:#334155}.drawer-footer,.detail-actions,.fault-list-actions{display:flex;justify-content:flex-end;align-items:center;gap:12px}.fault-list-actions{margin-top:12px;color:#94a3b8;font-size:12px}.detail-actions{margin-top:18px}@media(max-width:720px){.task-filter-form{display:block}.model-filter-item :deep(.el-select){width:100%}.metric-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.target-row{flex-direction:column}.target-row>*:first-child{width:100%}}
</style>
